-- ============================================================================
-- TemoDB v2 · 20 · geo reference data — copied from production (same ids):
-- 193 countries · 54 regions · 207 districts. Column "order" → sort_order.
-- ============================================================================

-- per-country settings for the country the system runs in today
UPDATE countries
   SET currency_code = 'UZS', default_locale = 'uz', locales = '{uz,ru,en}', timezone = 'Asia/Tashkent',
       phone_mask = '+998 ## ###-##-##', is_enabled = true
 WHERE code = 'UZ';

-- neighbours get sensible defaults but stay disabled until a deployment is agreed
UPDATE countries SET currency_code = 'KZT', timezone = 'Asia/Almaty',    phone_mask = '+7 ### ###-##-##'  WHERE code = 'KZ';
UPDATE countries SET currency_code = 'KGS', timezone = 'Asia/Bishkek',   phone_mask = '+996 ### ###-###'  WHERE code = 'KG';
UPDATE countries SET currency_code = 'TJS', timezone = 'Asia/Dushanbe',  phone_mask = '+992 ## ###-####'  WHERE code = 'TJ';
UPDATE countries SET currency_code = 'TMT', timezone = 'Asia/Ashgabat',  phone_mask = '+993 ## ##-##-##'  WHERE code = 'TM';

-- tuman vs shahar
UPDATE districts SET kind = 'city' WHERE name ~* '(^|\s)shah(a)?r(i)?(\s|$)';
